function billing_json(int $status, array $payload): void { http_response_code($status); echo json_encode($payload, JSON_UNESCAPED_SLASHES | JSON_INVALID_UTF8_SUBSTITUTE); exit; }
function billing_body(): array { $raw=file_get_contents('php://input'); if (!is_string($raw)||strlen($raw)>32768) billing_json(413,['error'=>'Request body is too large.']); $data=json_decode($raw,true); return is_array($data)?$data:[]; }
function billing_same_origin(): void { $origin=(string)($_SERVER['HTTP_ORIGIN']??''); if ($origin==='') return; $https=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')||strtolower((string)($_SERVER['HTTP_X_FORWARDED_PROTO']??''))==='https';$expected=($https?'https':'http').'://'.($_SERVER['HTTP_HOST']??''); if(!hash_equals($expected,$origin)) billing_json(403,['error'=>'Cross-origin request rejected.']); }
function billing_csrf(): void { billing_same_origin(); $t=$_SERVER['HTTP_X_CSRF_TOKEN']??null; if(!akh_csrf_verify(is_string($t)?$t:null)) billing_json(403,['error'=>'Session security token expired. Refresh the page and try again.']); }
function billing_admin(): string { $isBilling=(isset($_SESSION['akh_billing_user'])&&is_string($_SESSION['akh_billing_user'])); $u=$isBilling?$_SESSION['akh_billing_user']:akh_admin_current(); if($u===null||$u==='') billing_json(401,['error'=>'Sign in required.']); $db=billing_pdo(); $s=$db->prepare("SELECT username,role FROM users WHERE LOWER(username)=LOWER(?) AND role IN ('admin','accountant') LIMIT 1"); $s->execute([$u]); $row=$s->fetch(PDO::FETCH_ASSOC); if(!$row){if($isBilling)unset($_SESSION['akh_billing_user']);else akh_admin_logout();unset($_SESSION['akh_billing_role']);billing_json(401,['error'=>'This billing account is no longer active.']);} $role=(string)$row['role']; if(($role==='accountant'&&!$isBilling)||($role==='admin'&&$isBilling)||(!isset($_SESSION['akh_billing_role'])&&$role!=='admin')||(isset($_SESSION['akh_billing_role'])&&!hash_equals((string)$_SESSION['akh_billing_role'],$role))){if($isBilling)unset($_SESSION['akh_billing_user']);else akh_admin_logout();unset($_SESSION['akh_billing_role']);billing_json(401,['error'=>'This billing account is no longer active.']);} $_SESSION['akh_billing_role']=$role; return (string)$row['username']; }
function billing_pdo(): PDO { $db=function_exists('akh_db')?akh_db():null; if(!$db instanceof PDO) billing_json(503,['error'=>'Billing database is not configured. Configure MariaDB and apply the billing schema.']); return $db; }
function billing_n8n_auth(): void { $secret=defined('AKH_BILLING_N8N_TOKEN')?(string)AKH_BILLING_N8N_TOKEN:(string)(getenv('AKH_BILLING_N8N_TOKEN')?:''); $h=(string)($_SERVER['HTTP_AUTHORIZATION']??$_SERVER['REDIRECT_HTTP_AUTHORIZATION']??''); $provided=preg_match('/^Bearer\s+(.+)$/i',$h,$m)?trim($m[1]):''; if($secret===''||$provided===''||!hash_equals($secret,$provided)) billing_json(401,['error'=>'Invalid n8n credentials.']); }
function billing_audit(PDO $db,int $id,string $actor,string $action,array $details): void { $s=$db->prepare('INSERT INTO billing_audit_log (billing_id, actor, action, details) VALUES (?, ?, ?, ?)'); $s->execute([$id,$actor,$action,json_encode($details,JSON_UNESCAPED_SLASHES)]); }
function billing_payment_clear_claim(PDO $db,int $invoiceId,string $username): string { try { $verified=$db->prepare("UPDATE billing_invoice_payment_links SET status='cleared',claim_verification_status='verified',verified_by=?,verified_at=UTC_TIMESTAMP(3),cleared_at=UTC_TIMESTAMP(3) WHERE invoice_id=? AND status IN ('active','claimed')");$verified->execute([$username,$invoiceId]);$q=$db->prepare('SELECT client_utr FROM billing_invoice_payment_links WHERE invoice_id=?');$q->execute([$invoiceId]);return (string)($q->fetchColumn()?:''); } catch(PDOException $e) { if(str_contains(strtolower($e->getMessage()),'billing_invoice_payment_links'))return '';throw $e; } }
$action=(string)($_GET['action']??''); $method=strtoupper((string)($_SERVER['REQUEST_METHOD']??'GET'));
if($action==='login'&&$method==='POST'){billing_csrf();$b=billing_body();$u=trim((string)($b['username']??''));$p=(string)($b['password']??'');if($u===''||strlen($u)>100||$p===''||strlen($p)>200)billing_json(400,['error'=>'Enter username and password.']);$tries=(array)($_SESSION['akh_billing_login_attempts']??[]);$tries=array_values(array_filter($tries,static fn($t)=>is_int($t)&&$t>time()-900));if(count($tries)>=10)billing_json(429,['error'=>'Too many sign-in attempts. Try again later.']);$roleReady=akh_billing_role_schema_ensure();$db=billing_pdo();$roleClause=$roleReady?"role IN ('admin','accountant')":"role='admin'";$s=$db->prepare("SELECT username,password_hash,role FROM users WHERE LOWER(username)=LOWER(?) AND ".$roleClause." LIMIT 1");$s->execute([$u]);$account=$s->fetch(PDO::FETCH_ASSOC);if(!$account||!password_verify($p,(string)$account['password_hash'])){$tries[]=time();$_SESSION['akh_billing_login_attempts']=$tries;billing_json(401,['error'=>'Invalid accountant username or password.']);}session_regenerate_id(true);if((string)$account['role']==='accountant'){akh_admin_logout();$_SESSION['akh_billing_user']=strtolower((string)$account['username']);}else{unset($_SESSION['akh_billing_user']);$_SESSION['akh_admin_user']=strtolower((string)$account['username']);}$_SESSION['akh_billing_role']=(string)$account['role'];unset($_SESSION['akh_billing_login_attempts']);billing_json(200,['user'=>['username'=>(string)$account['username'],'role'=>(string)$account['role']]]);}
if($action==='logout'&&$method==='POST'){billing_csrf();if(isset($_SESSION['akh_billing_user']))unset($_SESSION['akh_billing_user']);else akh_admin_logout();unset($_SESSION['akh_billing_role']);billing_json(200,['ok'=>true]);}
if($action==='me'&&$method==='GET')billing_json(200,['user'=>['username'=>billing_admin(),'role'=>(string)($_SESSION['akh_billing_role']??'admin')],'mode'=>'mariadb']);
if(str_starts_with($action,'n8n-')){
 billing_n8n_auth();$db=billing_pdo();
 if($action==='n8n-eligible'&&$method==='GET'){$s=$db->query("SELECT id,task_code,drive_file_id,file_name,phone,customer_name FROM final_delivery_billing WHERE invoice_status='sent' AND payment_status='cleared' AND delivery_status='ready' ORDER BY cleared_at ASC");billing_json(200,['items'=>$s->fetchAll(PDO::FETCH_ASSOC)]);}
 if(preg_match('/^n8n-claim-(\d+)$/',$action,$m)&&$method==='POST'){$id=(int)$m[1];try{$db->beginTransaction();$s=$db->prepare("SELECT * FROM final_delivery_billing WHERE id=? AND invoice_status='sent' AND payment_status='cleared' AND delivery_status='ready' FOR UPDATE");$s->execute([$id]);$row=$s->fetch(PDO::FETCH_ASSOC);if(!$row){$db->rollBack();billing_json(409,['error'=>'Record is not eligible; invoice and payment clearance are required.']);}$claim=bin2hex(random_bytes(18));$u=$db->prepare("UPDATE final_delivery_billing SET delivery_status='processing',delivery_claim_token=?,delivery_claimed_at=UTC_TIMESTAMP(3),delivery_error=NULL WHERE id=?");$u->execute([$claim,$id]);$db->commit();$row['delivery_status']='processing';$row['delivery_claim_token']=$claim;billing_json(200,['item'=>$row]);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}
 if(preg_match('/^n8n-complete-(\d+)$/',$action,$m)&&$method==='POST'){$id=(int)$m[1];$b=billing_body();$claim=(string)($b['claim_token']??'');$status=(string)($b['status']??'');$link=isset($b['final_link'])?trim((string)$b['final_link']):null;$error=isset($b['error'])?substr((string)$b['error'],0,1000):null;if($claim===''||!in_array($status,['delivered','failed'],true)||($status==='delivered'&&(!is_string($link)||!filter_var($link,FILTER_VALIDATE_URL)||!str_starts_with($link,'https://'))))billing_json(400,['error'=>'Invalid delivery result.']);$s=$db->prepare("UPDATE final_delivery_billing SET delivery_status=?,final_link=?,delivered_at=IF(?='delivered',UTC_TIMESTAMP(3),delivered_at),delivery_error=?,delivery_claim_token=NULL WHERE id=? AND delivery_claim_token=? AND payment_status='cleared'");$s->execute([$status,$link,$status,$error,$id,$claim]);if($s->rowCount()!==1)billing_json(409,['error'=>'Claim is stale or payment is not cleared.']);billing_audit($db,$id,'n8n',$status==='delivered'?'delivered':'delivery_failed',['delivery_status'=>$status]);billing_json(200,['ok'=>true]);}
 billing_json(404,['error'=>'Unknown n8n action.']);
}
$username=billing_admin();
if($action==='billing'&&$method==='GET'){$db=billing_pdo();try{$s=$db->query("SELECT b.id,b.task_code,b.phone,b.customer_name,b.project_name,b.task_type,b.folder_id,b.drive_file_id,b.file_name,b.mime_type,b.file_size,b.bill_amount,b.invoice_number,b.invoice_file_url,b.source_invoice_id,b.billing_group_mode,b.billing_group_key,b.invoice_status,b.payment_status,b.payment_reference,b.cleared_by,b.cleared_at,b.delivery_status,b.final_link,b.delivered_at,b.created_at,p.payment_claimed_at,p.client_utr,p.claim_verification_status AS payment_verification_status FROM final_delivery_billing b LEFT JOIN billing_invoice_payment_links p ON p.invoice_id=b.source_invoice_id ORDER BY b.created_at DESC");}catch(PDOException $e){$message=strtolower($e->getMessage());if(str_contains($message,'billing_invoice_payment_links')){$s=$db->query('SELECT id,task_code,phone,customer_name,project_name,task_type,folder_id,drive_file_id,file_name,mime_type,file_size,bill_amount,invoice_number,invoice_file_url,source_invoice_id,billing_group_mode,billing_group_key,invoice_status,payment_status,payment_reference,cleared_by,cleared_at,delivery_status,final_link,delivered_at,created_at,NULL AS payment_claimed_at,NULL AS client_utr,NULL AS payment_verification_status FROM final_delivery_billing ORDER BY created_at DESC');}elseif(str_contains($message,'payment_claimed'))billing_json(503,['error'=>'UPI payment claims migration is incomplete. Finish billing-dashboard/sql/006_upi_payment_claims.sql, then refresh.']);elseif(str_contains($message,'billing_group_mode')||str_contains($message,'billing_group_key'))billing_json(503,['error'=>'Project grouping is not installed yet. Import billing-dashboard/sql/005_billing_groups.sql, then refresh.']);elseif(str_contains($message,'source_invoice_id'))billing_json(503,['error'=>'Invoice linking is not installed yet. Import billing-dashboard/sql/003_link_invoices.sql, then refresh.']);elseif((string)$e->getCode()==='42S02'||str_contains($message,'final_delivery_billing'))billing_json(503,['error'=>'Billing tables are not installed yet. Import billing-dashboard/sql/001_php_hostinger.sql into the site database, then refresh.']);else throw $e;}billing_json(200,['items'=>$s->fetchAll(PDO::FETCH_ASSOC)]);}
if(($action==='group'||$action==='ungroup')&&$method==='POST'){
 billing_csrf();$db=billing_pdo();$b=billing_body();$ids=array_values(array_unique(array_filter(array_map('intval',(array)($b['ids']??[])),static fn($id)=>$id>0)));if(count($ids)>50||($action==='group'&&count($ids)<2)||($action==='ungroup'&&count($ids)<1))billing_json(400,['error'=>$action==='group'?'Select between 2 and 50 projects.':'Select at least 1 project to ungroup.']);
 $marks=implode(',',array_fill(0,count($ids),'?'));$db->beginTransaction();try{$q=$db->prepare("SELECT id,phone,customer_name,invoice_status,payment_status,source_invoice_id,delivery_status FROM final_delivery_billing WHERE id IN ($marks) FOR UPDATE");$q->execute($ids);$rows=$q->fetchAll(PDO::FETCH_ASSOC);if(count($rows)!==count($ids)){$db->rollBack();billing_json(404,['error'=>'One or more selected projects no longer exist.']);}foreach($rows as $row){if($row['invoice_status']!=='pending'||$row['payment_status']!=='unpaid'||$row['source_invoice_id']!==null||$row['delivery_status']!=='awaiting_payment'){$db->rollBack();billing_json(409,['error'=>'Only projects without an invoice or payment activity can be grouped or split.']);}}
 if($action==='group'){ $first=$rows[0];foreach($rows as $row){if(strtolower(trim((string)$row['phone']))!==strtolower(trim((string)$first['phone']))||strtolower(trim((string)$row['customer_name']))!==strtolower(trim((string)$first['customer_name']))){$db->rollBack();billing_json(409,['error'=>'A combined invoice requires the same customer name and phone number.']);}}$groupKey=bin2hex(random_bytes(16));$u=$db->prepare("UPDATE final_delivery_billing SET billing_group_mode='manual',billing_group_key=? WHERE id IN ($marks)");$u->execute(array_merge([$groupKey],$ids));$auditAction='projects_grouped';$details=['group_key'=>$groupKey,'project_ids'=>$ids]; }
 else { $u=$db->prepare("UPDATE final_delivery_billing SET billing_group_mode='single',billing_group_key=NULL WHERE id IN ($marks)");$u->execute($ids);$auditAction='projects_ungrouped';$details=['project_ids'=>$ids]; }
 foreach($ids as $id){billing_audit($db,$id,$username,$auditAction,$details);} $db->commit();billing_json(200,['ok'=>true,'message'=>$action==='group'?'Projects grouped for one invoice.':'Selected projects will be invoiced separately.']);
 }catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
}
if(preg_match('/^invoice-(\d+)$/',$action,$m)&&$method==='POST'){billing_csrf();billing_json(410,['error'=>'Manual invoice metadata is disabled. Create the invoice in the invoice builder so the PDF and invoice record are linked before it can be marked sent.']);}
if(preg_match('/^clear-(\d+)$/',$action,$m)&&$method==='POST'){
 billing_csrf();$db=billing_pdo();$id=(int)$m[1];$b=billing_body();$ref=trim((string)($b['payment_reference']??''));
 if(($b['actual_credit_confirmed']??false)!==true)billing_json(400,['error'=>'Confirm that the incoming credit is visible in the bank account before clearing.']);
 if($ref===''||strlen($ref)>255)billing_json(400,['error'=>'Enter the verified bank or UPI reference before clearing.']);
 $db->beginTransaction();try{
  $q=$db->prepare('SELECT source_invoice_id FROM final_delivery_billing WHERE id=? FOR UPDATE');$q->execute([$id]);$row=$q->fetch(PDO::FETCH_ASSOC);
  if(!$row){$db->rollBack();billing_json(404,['error'=>'Billing record not found.']);}
  $invoiceId=(int)($row['source_invoice_id']??0);
  if($invoiceId>0){$q=$db->prepare("SELECT id FROM final_delivery_billing WHERE source_invoice_id=? AND invoice_status='sent' AND payment_status IN ('unpaid','payment_claimed') FOR UPDATE");$q->execute([$invoiceId]);$ids=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));$count=$db->prepare('SELECT COUNT(*) FROM final_delivery_billing WHERE source_invoice_id=?');$count->execute([$invoiceId]);if(count($ids)!==(int)$count->fetchColumn()){$db->rollBack();billing_json(409,['error'=>'Every project on this invoice must be sent and not already cleared before clearing.']);}}
  else{$ids=[$id];}
  $marks=implode(',',array_fill(0,count($ids),'?'));$u=$db->prepare("UPDATE final_delivery_billing SET payment_status='cleared',payment_reference=?,cleared_by=?,cleared_at=UTC_TIMESTAMP(3),delivery_status='ready' WHERE id IN ($marks) AND invoice_status='sent' AND payment_status IN ('unpaid','payment_claimed')");$u->execute(array_merge([$ref,$username],$ids));
  if($u->rowCount()!==count($ids)){$db->rollBack();billing_json(409,['error'=>'Send an invoice before recording cleared payment.']);}
